<section class="content-section"><div class="container-xl"><div class="section-heading-row"><div><span class="section-kicker">Featured Properties</span><h2><?php echo esc_html(estatein_field('featured_heading',false,'Featured Properties')); ?></h2><p><?php echo esc_html(estatein_field('featured_description',false,'Explore our handpicked selection of featured properties. Each listing offers a glimpse into exceptional homes and investment opportunities.')); ?></p></div><?php echo estatein_button(estatein_field('featured_button_label',false,'View All Properties'),estatein_field('featured_button_url',false,estatein_archive_url('property')),'btn btn-outline-light'); ?></div><div class="row g-4 mt-2"><?php $ids=[]; for($i=1;$i<=3;$i++){ $id=(int)estatein_field('featured_property_'.$i,false); if($id)$ids[]=$id; } $args=['post_type'=>'property','posts_per_page'=>3,'post_status'=>'publish']; if($ids)$args['post__in']=$ids; $q=new WP_Query($args); if($q->have_posts()): while($q->have_posts()):$q->the_post(); ?>
<div class="col-lg-4"><article class="property-card h-100"><?php if(has_post_thumbnail()) the_post_thumbnail('estatein-property-card',['class'=>'property-card-image']); ?><div class="property-card-body"><h3><?php the_title(); ?></h3><p><?php echo esc_html(estatein_field('short_excerpt',get_the_ID(),wp_trim_words(get_the_excerpt(),24))); ?></p><div class="property-meta"><span>⌂ <?php echo esc_html(estatein_field('bedrooms',get_the_ID(),'—')); ?> Beds</span><span>▦ <?php echo esc_html(estatein_field('bathrooms',get_the_ID(),'—')); ?> Baths</span><span>▧ <?php echo esc_html(estatein_field('property_size',get_the_ID(),'—')); ?> <?php echo esc_html(estatein_field('property_size_unit',get_the_ID(),'sq ft')); ?></span></div><div class="property-price-row"><div><small>Price</small><strong><?php echo esc_html(estatein_currency(estatein_field('price',get_the_ID()))); ?></strong></div><a class="btn btn-primary" href="<?php the_permalink(); ?>">View Property</a></div></div></article></div>
<?php endwhile; wp_reset_postdata(); else: ?><div class="col-12"><div class="empty-state">Add Property posts and select up to three IDs in <strong>Homepage — 03 Featured Properties</strong>.</div></div><?php endif; ?></div></div></section>
